WEEKDAY_NAMES = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']


def schedules_from_json(apps, schema_editor):
    """Create weekly schedule rows from each doctor's availability_schedule JSON."""
    from apps.doctors.scheduling import parse_window

    Doctor = apps.get_model('doctors', 'Doctor')
    DoctorSchedule = apps.get_model('doctors', 'DoctorSchedule')
    rows = []
    for doctor in Doctor.objects.all():
        schedule = doctor.availability_schedule or {}
        if not isinstance(schedule, dict):
            continue
        for weekday, name in enumerate(WEEKDAY_NAMES):
            window = parse_window(schedule.get(name))
            if window:
                rows.append(DoctorSchedule(doctor=doctor, weekday=weekday,
                                           start_time=window[0], end_time=window[1]))
    DoctorSchedule.objects.bulk_create(rows)


